    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Locate a solid guide line and distinguish the sparse object from background.
    guide_row = next((r for r in range(h) if len(set(grid[r])) == 1), None)
    guide_col = next((c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1), None)
    if guide_row is not None:
        guide_color = grid[guide_row][0]
    elif guide_col is not None:
        guide_color = grid[0][guide_col]
    else:
        return out
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    candidates = [v for v in counts if v not in (guide_color, background)]
    if not candidates:
        return out
    obj = min(candidates, key=counts.get)
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == obj]
    if guide_row is not None:
        target = max(r for r, c in cells) + 1
        if target < h:
            out[target] = [8] * w
    else:
        target = max(c for r, c in cells) + 1
        if target < w:
            for r in range(h):
                out[r][target] = 8
    return out
